        [Fact(DisplayName = "handiwork > repair a damaged door, then barricade it with wood, then reinforce it")]
        public void T002_repair_a_damaged_door_then_barricade_it_with_wood_then_reinf()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["sD."] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            cmd(state, new Command { type = "takeControl", survivorId = s.id });
            Breach.damageStructure(state, 1, 0, 100);
            expect(Breach.structureDamage(state, 1, 0)).toBeGreaterThan(0);
            expect(Commands.applyCommand(state, new Command { type = "work", x = Js.I(1), y = Js.I(0) }).ok).toBe(true);
            run(state, 80);
            expect(Breach.structureDamage(state, 1, 0)).toBe(0);
