            run(state, Designations.BUILD_WORK["barricade"] + 2);
            expect(Grids.getTile(state.grid, 1, 0)).toBe("barricade");
            expect(s.carrying).toBeNull();
            holdWood(state);
            cmd(state, new Command { type = "work", x = Js.I(1), y = Js.I(0) });
