        [Fact(DisplayName = "handiwork > forage on open grass by day: sometimes food; each tile once a day")]
        public void T004_forage_on_open_grass_by_day_sometimes_food_each_tile_once_a_()
        {
            double found = 0;
            for (var seed = 1; seed <= 12; seed++)
            {
                var state = ScenarioMod.loadScenario(new Scenario { seed = seed, map = ["s.."] });
                state.grid.ground.fill(Grids.GROUNDS.indexOf("grass"));
                var s = Js.NN(Js.Get(state.survivors, 0));
                s.id = $"s{Js.Str(seed * 7)}";
                state.control = new Control { survivorId = s.id, dx = 0, dy = 0, facing = new Point { x = Js.I(1), y = Js.I(0) }, nextSwing = 0, busy = null };
                state.tick = Js.I(2 * Time.TICKS_PER_HOUR);
                cmd(state, new Command { type = "use", x = Js.I(0), y = Js.I(0) });
                run(state, Handiwork.FORAGE_TICKS + 2);
                found += state.items.filter((i) => i.kind == "food").length;
                state.items = [];
                var again = Commands.applyCommand(state, new Command { type = "use", x = Js.I(0), y = Js.I(0) });
                expect(again.ok).toBe(true);
                expect(Js.NN(state.control).busy).toBeNull();
            }
            expect(found).toBeGreaterThan(0);
            expect(found).toBeLessThan(12);
        }

